320	    /// least one path under one of `pathspecs`.
321	    ///
322	    /// `pathspecs` match as directory/path prefixes against a commit's tree
323	    /// diff vs. its first parent -- mirrors `git log -- <pathspecs>`'s
324	    /// scoping, not full git pathspec magic (`:!`, globs, etc). Empty
325	    /// `pathspecs` disables filtering (all commits, like `git log` with no
326	    /// trailing `--`).
327	    ///
328	    /// `since` is exclusive, same as `commits_since`. Merge commits are
329	    /// skipped (`--no-merges`), since a merge's message duplicates work its
330	    /// non-merge ancestors already represent -- this powers per-package
331	    /// commit scoping for severity inference.
332	    pub fn commits_since_with_pathspec(
333	        &self,
334	        since: Option<&CommitSha>,
335	        pathspecs: &[PathBuf],
336	    ) -> Result<Vec<GitCommit>, VcsError> {
337	        #[cfg(not(target_arch = "wasm32"))]
338	        {
339	            let head = self
340	                .repo
341	                .head_commit()
342	                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
343	
344	            let mut platform = self.repo.rev_walk(vec![head.id]);
345	
346	            // Bound the walk with gix's own hidden-tip frontier algorithm
347	            // (`git log since..HEAD` semantics) instead of a second,
348	            // unbounded full-history walk from `since` collected into an
349	            // exclusion set. `with_hidden` paints the overlap between the
350	            // visible (HEAD) and hidden (`since`) tips using generation
351	            // numbers and refuses to enqueue parents once a commit is known
352	            // to be hidden-only ancestry, so the walk stops once every
353	            // in-flight branch has been resolved instead of continuing to
354	            // the repository's first commit. This preserves the same
355	            // branchy-history correctness the old two-walk-then-exclude
356	            // approach needed a manual `continue`-not-`break` exclusion set
357	            // for (a topological walk can visit `since` before it has
358	            // emitted all commits on branches that diverged before it) --
359	            // gix's frontier computation is exactly the same "boundary
360	            // commit" algorithm `git rev-list branch ^tag` itself uses, so
361	            // it handles that case internally rather than needing it
362	            // reimplemented here. `since` remains exclusive, matching the
363	            // prior behavior: `with_hidden` excludes both the hidden tip
364	            // itself and everything reachable from it.
365	            if let Some(s) = since {
366	                let since_oid = gix::ObjectId::from_hex(s.as_ref().as_bytes())
367	                    .map_err(|e| VcsError::Git(format!("Invalid since SHA: {e}")))?;
368	                platform = platform.with_hidden(Some(since_oid));
369	            }
370	
371	            let revwalk = platform
372	                .all()
373	                .map_err(|e| VcsError::Git(format!("Failed to create revwalk: {e}")))?;
374	
375	            let mut commits = Vec::new();
376	            for info in revwalk {
377	                let info = info.map_err(|e| VcsError::Git(e.to_string()))?;
378	                REVWALK_VISIT_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
379	                let hex = info.id.to_hex().to_string();
380	
381	                if info.parent_ids().count() > 1 {
382	                    continue;
383	                }
384	
385	                let commit_obj = info
386	                    .object()
387	                    .map_err(|e| VcsError::Git(format!("Failed to load commit object: {e}")))?;
388	
389	                if !pathspecs.is_empty() {
390	                    let touched = commit_touches_pathspecs(&self.repo, &info, &commit_obj, pathspecs)?;
391	                    if !touched {
392	                        continue;
393	                    }
394	                }
395	
396	                let sha = CommitSha::parse(&hex).map_err(|e| VcsError::Git(format!("Invalid commit SHA: {e}")))?;
397	
398	                let message = commit_obj.message().map_err(|e| VcsError::Git(e.to_string()))?;
399	                let summary = message.title.to_string().replace("\r\n", "\n").trim_end().to_string();
400	                let body = message.body.map(|b| b.to_string().replace("\r\n", "\n"));
401	
402	                commits.push(GitCommit { sha, summary, body });
403	            }
404	
405	            Ok(commits)
406	        }
407	        #[cfg(target_arch = "wasm32")]
408	        {
409	            let _unused = (since, pathspecs);
410	            Ok(Vec::new())
411	        }
412	    }
