414	    pub fn create_tag(
415	        &self,
416	        name: &str,
417	        target_sha: &CommitSha,
418	        message: Option<&str>,
419	        _permit: &ApplyPermit,
420	    ) -> Result<(), VcsError> {
421	        #[cfg(not(target_arch = "wasm32"))]
422	        {
423	            let oid = gix::ObjectId::from_hex(target_sha.as_ref().as_bytes())
424	                .map_err(|e| VcsError::Git(format!("Invalid SHA: {e}")))?;
425	
426	            if let Some(msg) = message {
427	                self.repo
428	                    .tag(
429	                        name,
430	                        oid,
431	                        gix::object::Kind::Commit,
432	                        None,
433	                        msg,
434	                        gix::refs::transaction::PreviousValue::MustNotExist,
435	                    )
436	                    .map_err(|e| VcsError::Git(format!("Failed to create tag: {e}")))?;
437	            } else {
438	                let clean_name = name.strip_prefix("refs/tags/").unwrap_or(name);
439	                let ref_name = format!("refs/tags/{}", clean_name);
440	                let _unused = self
441	                    .repo
442	                    .reference(
443	                        ref_name,
444	                        oid,
445	                        gix::refs::transaction::PreviousValue::MustNotExist,
446	                        "callisto create tag",
447	                    )
448	                    .map_err(|e| VcsError::Git(format!("Failed to create lightweight tag: {e}")))?;
449	            }
450	            Ok(())
451	        }
452	        #[cfg(target_arch = "wasm32")]
453	        {
454	            let _ = (name, target_sha, message);
455	            Err(VcsError::Git("WASM unsupported".to_string()))
456	        }
457	    }
