491	/// Diffs `commit_obj`'s tree against its first parent's tree (or the empty
492	/// tree, for a root commit) and reports whether any changed path falls
493	/// under one of `pathspecs`.
494	#[cfg(not(target_arch = "wasm32"))]
495	fn commit_touches_pathspecs(
496	    repo: &gix::Repository,
497	    info: &gix::revision::walk::Info<'_>,
498	    commit_obj: &gix::Commit<'_>,
499	    pathspecs: &[PathBuf],
500	) -> Result<bool, VcsError> {
501	    let commit_tree = commit_obj
502	        .tree()
503	        .map_err(|e| VcsError::Git(format!("Failed to load commit tree: {e}")))?;
504	
505	    let parent_tree = match info.parent_ids().next() {
506	        Some(parent_id) => {
507	            let parent_commit = parent_id
508	                .object()
509	                .map_err(|e| VcsError::Git(format!("Failed to load parent commit object: {e}")))?
510	                .into_commit();
511	            parent_commit
512	                .tree()
